WITH base AS (SELECT id, order_id, paid_at, status, LOWER(method) AS method_lower, HOUR(paid_at) AS paid_at_hour FROM payments WHERE paid_at > TO_DATE('2023-10-16') AND method IS DISTINCT FROM 'cash'), enriched AS (SELECT id, paid_at, status, method_lower, paid_at_hour, LEAD(paid_at_hour) OVER w_ordered AS next_paid_at_hour, ROW_NUMBER() OVER w_ordered AS seq_no, RANK() OVER (PARTITION BY TO_DATE(paid_at), status ORDER BY paid_at_hour ASC) AS paid_at_hour_rank FROM base WINDOW w_ordered AS (PARTITION BY status ORDER BY paid_at_hour ASC, id ASC)), with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM enriched), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps), remaining_keys AS (SELECT status FROM sessionized EXCEPT ALL SELECT status FROM payments WHERE order_id IN (9, 24, 28)), verified AS (SELECT s.* FROM sessionized s JOIN remaining_keys k ON s.status = k.status), filtered AS (SELECT *, CAST(is_new_session AS DOUBLE) AS is_new_session_str FROM verified WHERE paid_at >= DATE '2023-08-07'), filtered_payments AS (SELECT *, CASE WHEN session_id >= 6 THEN 'High' WHEN session_id >= 4 THEN 'Medium' ELSE 'Low' END AS session_id_tier FROM filtered WHERE paid_at >= TIMESTAMP '2023-10-20 06:00:00' AND seq_no <= 3), enriched_payments AS (SELECT id, paid_at, status, paid_at_hour, next_paid_at_hour, seq_no, session_id, session_id_tier, CUME_DIST() OVER (PARTITION BY status ORDER BY is_new_session DESC) AS is_new_session_cume_dist FROM filtered_payments) SELECT id, seq_no, session_id, session_id_tier, is_new_session_cume_dist FROM enriched_payments ORDER BY is_new_session_cume_dist ASC, id ASC;
